    H=len(g); W=len(g[0]); res=[]
    if axis=='h':
        for r in range(H):
            c=0
            while c<W:
                if g[r][c]!=0:
                    v=g[r][c]; s=c
                    c+=1
                    while c<W and g[r][c]==v: c+=1
                    res.append(('h',r,s,c-1,v))
                else: c+=1
    else:
        for c in range(W):
            r=0
            while r<H:
                if g[r][c]!=0:
                    v=g[r][c]; s=r
                    r+=1
                    while r<H and g[r][c]==v: r+=1
                    res.append(('v',c,s,r-1,v))
                else: r+=1
    return res

def solve(g):
    H=len(g); W=len(g[0]); out=[r[:] for r in g]
    vr=runs(g,'v'); hr=runs(g,'h')
    # empty rows/cols: rows/cols with no nonzero cell
    empty_rows={r for r in range(H) if all(g[r][c]==0 for c in range(W))}
    empty_cols={c for c in range(W) if all(g[r][c]==0 for r in range(H))}
    # target rows: empty rows inside a v-run's span; target cols: empty cols inside an h-run's span
    trs=[]; tcs=[]
    for rv in vr:
        if len(empty_rows & set(range(rv[3]+1)): pass
        rows=set(range(rv[2],rv[3]+1))
        for r in sorted(empty_rows & rows): trs.append((r,rv))
    for rh in hr:
        cols=set(range(rh[3]+1)) if False else set(range(rh[2],rh[3]+1))
        for c in sorted(empty_cols & cols): tcs.append((c,rh))
    # assignments: each (tr,tcs) combo gets value from a run; resolve conflicts by nearest run
    assigns={}
    for r,tv in trs:
        for c,th in tcs:
            if th['type']=='h' and tv['type']=='v':
                cands=[]
                for hh in hr:
                    if hh[1]<=c<=hh[4]:
                        d=abs(hh[1]-r)
                        cands.append((d,hh[1],hh[5]))
                for vv in vr:
                    if vv[1]<=r<=vv[4]:
                        d=abs(vv[1]-c)
                        cands.append((d,None,vv[5]))
                if cands:
                    cands.sort()
                    val=cands[0][2]
                    assigns[(r,c)]=val
    for (r,c),v in assigns.items():
        out[r][c]=v
    return out

