def comps_of(g,bg):
    h=len(g);w=len(g[0]);seen=set();out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));cl=[]
                while st:
                    x,y=st.pop();cl.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<h and 0<=b<w and g[a][b]==g[x][y] and (a,b) not in seen:
                            seen.add((a,b));st.append((a,b))
                out.append(cl)
    return out
